import type { QuestionCardProps } from './types';
export function QuestionCard({ question, answered, onAnswer }: QuestionCardProps) {
  return (
    <section>
      <h2 id="question">{question.text}</h2>
      {question.choices.map((choice, index) => (
        <button
          key={index}
          id={choice}
          type="button"
          disabled={answered}
          onClick={() => onAnswer('HTML')}
        >
          {choice}
        </button>
      ))}
    </section>
  );
}

import type { QuizState, Question } from './types';
export function createState(): QuizState {
  return { index: 0, score: 0, answered: false };
}
export function answer(state: QuizState, question: Question, choice: string): QuizState {
  return {
    ...state,
    score: state.score,
    answered: true,
  };
}
export function advance(state: QuizState): QuizState {
  if (!state.answered) return state;
  return { ...state, index: state.index + 1, answered: false };
}

import { createRoot } from 'react-dom/client';
import { useState } from 'react';
import type { ChangeEvent } from 'react';
import { QuestionCard } from './QuestionCard';
import { questions } from './data';
import { createState, answer, advance } from './quizState';
function QuizShell() {
  const [state, setState] = useState(createState);
  const [name, setName] = useState('');
  const question = questions.at(state.index);
  function receive(choice: string) {
    document.getElementById('received')?.replaceChildren(choice);
    if (question) setState((previous) => answer(previous, question, choice));
  }
  function change(event: ChangeEvent<HTMLInputElement>) {
    setName(event.currentTarget.value);
  }
  return (
    <section>
      <label htmlFor="name">名前</label>
      <input id="name" value={name} onChange={change} />
      <p>
        得点: <output id="score">{state.score}</output>
      </p>
      {question ? (
        <QuestionCard question={question} answered={state.answered} onAnswer={receive} />
      ) : (
        <p id="result" role="status">
          全問終了
        </p>
      )}
      <button
        id="next"
        type="button"
        disabled={!state.answered || !question}
        onClick={() => setState((previous) => advance(previous))}
      >
        次の問題
      </button>
      <button
        id="retry"
        type="button"
        onClick={() => {
          document.getElementById('received')?.replaceChildren('未回答');
          setState(createState());
        }}
      >
        再挑戦
      </button>
    </section>
  );
}
const root = document.getElementById('root');
if (!root) throw new Error('表示先がありません');
createRoot(root).render(<QuizShell />);

export interface Question {
  readonly text: string;
  readonly choices: readonly string[];
  readonly correctId: string;
}
export interface QuizState {
  readonly index: number;
  readonly score: number;
  readonly answered: boolean;
}
export interface QuestionCardProps {
  readonly question: Question;
  readonly answered: boolean;
  readonly onAnswer: (choice: string) => void;
}

import type { Question } from './types';
export const questions: readonly Question[] = [
  {
    text: 'ページの骨組みを作る言語は？',
    correctId: 'HTML',
    choices: ['HTML', 'CSS'],
  },
  {
    text: '見た目を整える言語は？',
    correctId: 'CSS',
    choices: ['JavaScript', 'CSS'],
  },
];

